-- SQL dump of ephemerides and monthly_values from Supabase to D1
CREATE TABLE IF NOT EXISTS ephemerides (id TEXT PRIMARY KEY, day INTEGER NOT NULL, month INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, is_holiday INTEGER DEFAULT 0, category TEXT DEFAULT 'EDUCATIVA', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS monthly_values (month INTEGER PRIMARY KEY, value_name TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);

-- Insert Ephemerides
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('34ee8988-8957-4459-84ee-272d4b85684a', 20, 3, 'Día de la Francofonía', 'Celebración de la lengua francesa y la diversidad cultural de los países que la hablan. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('dacfa66b-e954-4e62-bc2b-095e057d63ab', 21, 3, 'Día Forestal, Poesía y Down', 'Jornada múltiple para el medio ambiente, la cultura literaria y la inclusión social. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('c43a5a23-afb2-4129-9e71-2df8ae1b09c3', 1, 10, 'Díadel Envejeciente y del Mercadólogo', 'Homenaje a los adultos mayores y a los profesionales del mercadeo. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('871a6862-dda7-41db-9423-3627fd2858b1', 6, 10, 'Día Mundial de la Parálisis Cerebral', 'Sensibilización sobre esta condición para fomentar la inclusión y el apoyo. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('19130614-469a-408d-8927-8c6b2aac9e81', 8, 10, 'Día del Bombero y de la Dislexia', 'Homenaje a los bomberos y concienciación sobre la dislexia en el aprendizaje. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f13b8baf-3016-47f4-8bab-940de118a2ac', 5, 10, 'Día Mundial de los Docentes', 'Día Mundial de los Docentes, establecido por la UNESCO para valorar y celebrar la labor transformadora de los maestros en la sociedad. Los docentes son los arquitectos del futuro, responsables de guiar el proceso de enseñanza-aprendizaje y de forjar el pensamiento crítico en los niños y jóvenes. Esta fecha es un llamado a mejorar sus condiciones laborales y reconocer su papel central en la construcción de sociedades más equitativas, pacíficas y prósperas. En las aulas dominicanas, los maestros son los motores que impulsan el desarrollo intelectual y moral de la patria.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f78f8f9f-5daa-474e-af2d-f65c1a244faa', 16, 10, 'Día de la Alimentación y del Técnico de Farmacia', 'Fomenta la seguridad alimentaria y reconoce al personal técnico de farmacia. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('88280b47-4cfb-4342-b7d5-c885043fd79c', 18, 10, 'Protección de la Naturaleza', 'Llamado a la conservación de los ecosistemas y la biodiversidad del planeta. La protección de nuestro entorno natural es una responsabilidad ética inalienable que tenemos con las presentes y futuras generaciones. Esta efeméride ambiental nos recuerda la fragilidad de nuestros ecosistemas, desde las cuencas hidrográficas hasta la biodiversidad marina de nuestra isla. Promover una conciencia ecológica activa en nuestras escuelas es vital para enfrentar los desafíos del cambio climático y garantizar la sostenibilidad de nuestros recursos naturales. Cuidar el medio ambiente es, en última instancia, cuidar la casa de todos y asegurar la continuidad de la vida en el planeta.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('af9996d0-5856-4a4e-b0f1-ff5378b57a51', 5, 8, 'Fundación de la ciudad de Santo Domingo (1498)', 'Conmemoración de la fundación de la Ciudad Primada de América por Bartolomé Colón en la margen oriental del río Ozama en 1498 (trasladada luego a la occidental por Nicolás de Ovando). Santo Domingo se convirtió rápidamente en el centro administrativo, cultural y religioso del Nuevo Mundo, albergando las primeras instituciones europeas en el continente americano, como la primera catedral y la primera universidad. Es el corazón histórico de la isla y un testimonio viviente del inicio del encuentro entre dos culturas, declarada Patrimonio de la Humanidad.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('90bc2cf9-6f61-4ccc-957b-0634d40bf383', 16, 8, 'Restauración de la República (1863)', 'Gesta patriótica iniciada con el histórico Grito de Capotillo, liderado por Santiago Rodríguez y un grupo de valientes dominicanos en 1863. Esta lucha armada representó la determinación de un pueblo por recuperar su soberanía tras la vergonzosa anexión a España perpetrada por Pedro Santana en 1861. A través de una feroz guerra de guerrillas, los restauradores demostraron que la identidad y la libertad dominicana eran innegociables, logrando la salida definitiva de las tropas españolas en 1865 y reafirmando por segunda vez nuestra existencia como estado libre.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('93298031-4031-4d08-a40d-88babd055852', 7, 1, 'Poder Judicial y Moreno Jimenes', 'Eugenio María de Hostos, el "Ciudadano de América", transformó la educación dominicana a finales del siglo XIX con la creación de las Escuelas Normales. Su enfoque científico y ético buscaba formar "ciudadanos conscientes" capaces de razonar y servir a la sociedad. Paralelamente, en este mes se celebra el Día del Poder Judicial y el natalicio del poeta Domingo Moreno Jimenes, padre del postumismo. Ambas figuras resaltan la importancia del orden legal, la formación intelectual y la sensibilidad artística como pilares que sostienen el progreso y la estabilidad de una nación moderna.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f8c1d251-267f-4bed-a623-cccb017d3bcb', 11, 1, 'Natalicio de Hostos y Día de la Educación', 'Eugenio María de Hostos, el "Ciudadano de América", transformó la educación dominicana a finales del siglo XIX con la creación de las Escuelas Normales. Su enfoque científico y ético buscaba formar "ciudadanos conscientes" capaces de razonar y servir a la sociedad. Paralelamente, en este mes se celebra el Día del Poder Judicial y el natalicio del poeta Domingo Moreno Jimenes, padre del postumismo. Ambas figuras resaltan la importancia del orden legal, la formación intelectual y la sensibilidad artística como pilares que sostienen el progreso y la estabilidad de una nación moderna.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('24e3b820-d2b7-4679-a399-78a22c9dd56c', 13, 1, 'Día Nacional de la Alfabetización', 'La alfabetización es un derecho humano fundamental y el cimiento del aprendizaje a lo largo de toda la vida. Es esencial para el desarrollo social y humano, permitiendo a los ciudadanos participar plenamente en la sociedad, mejorar sus condiciones de vida y ejercer su libertad de manera informada y crítica.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('5af4ba66-ec31-49d9-8cae-d9261a15f7ff', 21, 1, 'Día de Nuestra Señora de la Altagracia', 'Día de Nuestra Señora de la Altagracia, considerada la madre protectora y espiritual del pueblo dominicano desde el siglo XVII. Esta festividad, la más importante del catolicismo dominicano, atrae anualmente a miles de peregrinos a la Basílica de Higüey. Más allá del ámbito religioso, la Virgen de la Altagracia es un símbolo cultural que ha acompañado la historia del pueblo dominicano en sus momentos de crisis y esperanza, uniendo a la nación en una identidad de fe compartida que trasciende clases sociales y regiones, siendo parte fundamental de nuestro patrimonio cultural.', 1, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('d0344832-f31a-4d27-a250-c19bd0522942', 6, 11, 'Día de la Constitución', 'Conmemoración de la firma de la primera Constitución dominicana en San Cristóbal el 6 de noviembre de 1844. Este documento es la ley suprema que organiza al Estado y garantiza los derechos ciudadanos, siendo el pilar fundamental del orden democrático y la institucionalidad nacional. La Constitución de San Cristóbal estableció la forma de gobierno republicana, civil y representativa, y aunque ha sufrido numerosas reformas a lo largo de nuestra historia, sigue representando el pacto social y político que define nuestra convivencia y soberanía como pueblo libre.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('a8297b88-7a31-4be4-933e-e4afbdc8c5a3', 8, 11, 'Natalicio de Mamá Tingó (1921)', 'Florinda Soriano, conocida como Mamá Tingó, fue una valiente líder campesina y activista por los derechos de la tierra en la República Dominicana. Su lucha incansable contra el despojo injusto de terrenos a los labradores de Hato Viejo la convirtió en un símbolo eterno de justicia social y resistencia rural. Asesinada en 1974 por defender la propiedad colectiva, su legado inspira a las nuevas generaciones a valorar la dignidad del trabajo agrícola y la importancia de la equidad en la distribución de la riqueza y el respeto a la vida humana.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('740ed77e-99e2-4566-9991-b2c110f7daed', 1, 11, 'Día de Todos los Santos', 'Festividad religiosa en honor a todos los santos conocidos y desconocidos. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('97b01c47-b7c0-4434-a3df-21aef6ccc415', 2, 11, 'Día de los Difuntos', 'Día dedicado a recordar y honrar la memoria de los seres queridos fallecidos. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b4d9ab7e-d284-4e9d-bac6-ac93ce3d6809', 7, 11, 'Día del Deporte', 'Fomento de la actividad física y los valores de la disciplina y el trabajo en equipo. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('7b991817-66a5-4b56-84be-78ad97afec60', 9, 11, 'Día Internacional del Inventor', 'Reconocimiento a la creatividad y los aportes de los inventores a la humanidad. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('29bff833-200a-4565-8c12-0b402a355192', 10, 11, 'Natalicio de Evangelina Rodríguez y Día de la Ciencia', 'Homenaje a la primera mujer dominicana en graduarse de medicina. A pesar de las barreras sociales de su época, se dedicó al servicio de los más necesitados y a la salud preventiva, siendo una pionera de la ciencia y los derechos de la mujer. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4e754a44-91f1-4049-820e-87da20540f75', 7, 12, 'Natalicio de Ercilia Pepín (1886)', 'Destacada educadora, intelectual y feminista dominicana que revolucionó el sistema escolar nacional con un enfoque humanista, científico y profundamente patriótico. Como directora de escuela y maestra, Ercilia Pepín fue una firme opositora a la intervención militar estadounidense de 1916, enseñando con el ejemplo los valores de civismo, honor y amor a la patria. Llevó la bandera dominicana en su pecho como acto de resistencia y promovió la educación de la mujer como herramienta para la liberación intelectual y el progreso real de la sociedad dominicana.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2db8703a-6246-4767-b6e0-631f06570003', 17, 8, 'Primera interpretación del Himno Nacional (1883)', 'En los salones de la Logia Esperanza No. 9 se escuchó por primera vez en 1883 la solemne música de José Reyes unida a la inspirada letra de Emilio Prud’Homme. Este símbolo patrio fundamental une a todos los dominicanos bajo un canto de valentía, honor y sacrificio que narra nuestra historia de luchas contra la opresión. Aunque enfrentó debates políticos iniciales sobre su letra, fue oficializado definitivamente en 1934, convirtiéndose en el alma de la nación y en el recordatorio diario de los valores de libertad, justicia y soberanía que debemos defender con orgullo.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('c105be7d-fdc8-41d7-ac35-5216cb811aac', 2, 2, 'Día Mundial de los Humedales', 'Concienciación sobre la importancia de los humedales para la biodiversidad y el equilibrio ecológico. Estos ecosistemas actúan como esponjas naturales que filtran el agua y protegen contra inundaciones. Es vital educar a los estudiantes sobre su preservación para garantizar un futuro ambiental sano en nuestra isla.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('5dcd60ee-074b-4730-b839-687845a8b132', 4, 2, 'Día Mundial del Mecánico', 'Reconocimiento a los profesionales dedicados al mantenimiento y reparación técnica de vehículos y maquinaria. Su labor es fundamental para la movilidad nacional y el funcionamiento industrial. En el ámbito educativo, destaca la importancia de la formación técnico-profesional para el desarrollo del país.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('8fbba059-4ff3-4c8d-b914-4d9a49770768', 10, 2, 'Día Nacional del Folklore', 'El Día Nacional del Folklore celebra la riqueza de nuestras raíces, tradiciones y expresiones culturales auténticas que definen el alma del pueblo dominicano. Desde el merengue y la bachata hasta nuestras artesanías, gastronomía y festividades populares como el carnaval, el folklore es un patrimonio vivo que debemos preservar y transmitir a las nuevas generaciones. En el ámbito educativo, este día es una oportunidad para que los estudiantes reconozcan su identidad cultural, valoren la diversidad de nuestras regiones y sientan el orgullo de pertenecer a una nación con una herencia tan vibrante y creativa.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('6c8a6c8d-29b3-4cf5-bac4-2b2674eb58f3', 9, 12, 'Prevención de Corrupción e Informática', 'Fomenta la ética pública y celebra los avances tecnológicos de la computación. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2fa2b0f0-5e02-454d-8871-2ce5d265777f', 10, 12, 'Día de los Derechos Humanos', 'Conmemoración de la Declaración Universal de los Derechos Humanos. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('694c57bd-fd30-46ec-9f64-d0d3ba473bd4', 3, 2, 'Natalicio de José Ramón López', 'Recuerdo del intelectual, ensayista y cuentista dominicano José Ramón López. Sus obras exploraron la realidad social del campo dominicano con una mirada crítica y profunda. Es un referente esencial para comprender la sociología dominicana de finales del siglo XIX y principios del XX. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('1ea8c70f-5602-4244-9553-0296d879288b', 6, 2, 'Día del Internet Seguro', 'Promueve el uso responsable y respetuoso de las tecnologías digitales. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2a9063ed-c753-44ef-9ec3-fe2ad6512a2c', 1, 9, 'Natalicio de Joaquín Balaguer (1906)', 'Nacimiento de una de las figuras más influyentes e intelectuales de la política dominicana del siglo XX en 1906. Como prolífico escritor, poeta y estadista, su vida pública abarcó desde la dictadura de Trujillo hasta la democracia moderna. Su legado está marcado por la construcción de grandes obras de infraestructura, presas y monumentos, pero también por una profunda influencia en la configuración autoritaria y luego transicional del Estado dominicano. Es una figura de estudio esencial para comprender la estabilidad, la economía y las dinámicas del poder en la historia contemporánea del país.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('e6bd118a-d283-49b4-b615-219210655789', 8, 9, 'Día Internacional de la Alfabetización', 'La alfabetización se reconoce hoy como un derecho humano fundamental y el cimiento del aprendizaje a lo largo de toda la vida. Es una herramienta esencial para el desarrollo social y económico, permitiendo a los ciudadanos participar plenamente en la vida democrática, mejorar su empleabilidad y ejercer su libertad de manera informada. En el contexto educativo dominicano, este día subraya la necesidad de eliminar las brechas de aprendizaje y garantizar que cada niño, joven y adulto tenga la capacidad de leer y escribir la realidad para transformarla positivamente.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b1d1c160-247c-4773-921e-1a6f9146d5a4', 8, 9, 'Natalicio de Gregorio Luperón (1839)', 'Celebración del natalicio del General Gregorio Luperón en 1839, figura cumbre de la Guerra de la Restauración y defensor del ideal democrático. Considerado la "Espada de la Restauración", Luperón fue un líder militar de gran integridad que rechazó el poder absoluto para defender la institucionalidad. Su pensamiento liberal y su rechazo a las anexiones extranjeras lo colocan como uno de los máximos referentes éticos de nuestra historia republicana. Promovió la educación y el progreso como los únicos caminos para la verdadera independencia de la República Dominicana.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('05932652-0dd0-41dc-b2a5-a85a7182fb2c', 9, 9, 'Día Mundial de la Agricultura', 'Homenaje a la labor vital de los agricultores dominicanos. La agricultura no solo es la base de nuestra seguridad alimentaria, sino también un pilar de nuestra economía exportadora y una tradición ancestral que conecta al hombre con la tierra, exigiendo respeto por el medio ambiente y sostenibilidad.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b6fb1d92-ef5e-49fc-8f62-2f7499b95fbe', 16, 9, 'Día de la Capa de Ozono', 'El Día Internacional de la Preservación de la Capa de Ozono busca sensibilizar al mundo sobre la fragilidad del escudo gaseoso que protege la vida en la Tierra de los rayos ultravioleta dañinos. Esta fecha conmemora la firma del Protocolo de Montreal en 1987, un ejemplo exitoso de cooperación global para eliminar los químicos que dañan este cinturón protector. Para los docentes, esta es una oportunidad clave para educar sobre la sostenibilidad ambiental, el cambio climático y la responsabilidad colectiva que tenemos de cuidar el planeta para las futuras generaciones.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('603d7b92-cfb4-43aa-bfd0-3627b001df52', 24, 9, 'Día de Nuestra Señora de las Mercedes', 'Día de Nuestra Señora de las Mercedes, proclamada patrona del pueblo dominicano desde la época colonial. Esta festividad religiosa, una de las más concurridas de la nación, tiene su centro en el Santo Cerro. Más allá de su significado de fe, esta fecha se integra en la identidad cultural del dominicano, representando la esperanza y la protección espiritual de la nación. Es un día de peregrinaje y reflexión que une a familias en torno a tradiciones de devoción que han perdurado a través de los siglos, formando parte esencial de nuestro patrimonio inmaterial.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('86d7374a-b2a2-44d4-80da-967e8cbec69e', 27, 9, 'Día Nacional de la Biblia', 'Día Nacional de la Biblia en la República Dominicana, único país del mundo que ostenta la Biblia abierta en el centro de su Escudo Nacional con el lema: "Y conoceréis la verdad, y la verdad os hará libres". Esta celebración resalta la influencia profunda de los principios bíblicos en la formación de la ética, los valores y la cultura dominicana. Es una oportunidad para que las escuelas promuevan el diálogo sobre la libertad de culto, los valores morales y la herencia histórica-religiosa que constituye uno de los pilares de la identidad de nuestra nación.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('43206dc2-d5be-4129-b722-3b27132e6c53', 27, 9, 'Día del Cacique Enriquillo', 'Homenaje al primer líder guerrillero de las Américas, quien lideró una rebelión armada contra la opresión española en la Sierra de Bahoruco en el siglo XVI. Enriquillo simboliza la resistencia heroica de los nativos frente al sistema de encomiendas. Su lucha culminó con un tratado de paz firmado por el propio emperador Carlos V, reconociendo la autonomía indígena en Boyá. Es un ejemplo histórico de dignidad, estrategia militar y defensa de los derechos humanos frente a la injusticia colonial, siendo un precursor fundamental de la soberanía en la isla.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f180e397-8f51-4fe5-af1d-3315a1e3b099', 21, 10, 'Natalicio de Salomé Ureña y Día del Poeta', 'Natalicio de la insigne Salomé Ureña de Henríquez en 1850, la más grande poeta y educadora dominicana. Pionera en la educación femenina con la fundación del Instituto de Señoritas, Salomé transformó el panorama intelectual de la mujer en el país. Su poesía patriótica y lírica llamó a la construcción de una nación moderna y civilizada basada en el conocimiento y el amor a la patria. Su legado perdura no solo en sus versos inmortales, sino también en el ejemplo de entrega y visión pedagógica que continuaron sus hijos y generaciones de maestros formados bajo sus ideales.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4ab0a796-5adc-4156-b6e9-664cce040f2c', 28, 10, 'Fundación de la UASD (1538)', 'Aniversario de la fundación de la Universidad Autónoma de Santo Domingo en 1538, por la Bula In Apostolatus Culmine del Papa Paulo III. Como la Universidad Primada de América, la UASD ha sido el faro de la educación superior en el continente. A lo largo de los siglos, esta institución ha jugado un papel determinante en la lucha por las libertades públicas, la democracia y el desarrollo científico de la República Dominicana, manteniendo su carácter de universidad pública, abierta y comprometida con los sectores más vulnerables de la sociedad.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('555d7360-9c3c-466a-aec6-72b5f25ec8ad', 1, 8, 'Inicio de transmisiones de La Voz Dominicana (1952)', 'Hito histórico que marcó el inicio de la era televisiva en la República Dominicana el 1 de agosto de 1952. La Voz Dominicana fue la primera planta televisora del país y la tercera en América Latina, sentando las bases de la comunicación audiovisual nacional y la cultura del entretenimiento massivo. Bajo la dirección de José Arismendy Trujillo (Petán), este medio no solo sirvió como herramienta de propaganda, sino también como una academia para músicos, locutores y artistas, transformando para siempre la forma en que los dominicanos consumen información y arte en la modernidad.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('a7be0bf9-69f1-4d76-a892-8e127aa19961', 2, 8, 'Juan Pablo Duarte parte al primer exilio (1843)', 'Momento de gran sacrificio personal para Juan Pablo Duarte en 1843, quien abandonó el país para evitar ser capturado por las autoridades haitianas tras el fracaso del movimiento de La Reforma. Este exilio fue fundamental para proteger su integridad física y poder continuar dirigiendo, a través de una intensa y valiente correspondencia, los esfuerzos independentistas de La Trinitaria. Su partida simboliza el desprendimiento absoluto de un líder que puso la libertad de su pueblo por encima de su estabilidad personal, inspirando a sus compañeros a concretar la independencia en 1844.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('ced25aa4-902a-4790-8fe8-1ba1147a6f97', 25, 11, 'Asesinato de las Hermanas Mirabal (1960)', 'Patria, Minerva y María Teresa Mirabal, conocidas como "Las Mariposas", fueron brutalmente asesinadas por la dictadura de Rafael L. Trujillo en 1960 debido a su valiente oposición al régimen. Su martirio se convirtió en un símbolo global de la lucha contra la violencia hacia la mujer y por la libertad nacional. Esta fecha, designada por la ONU como el Día Internacional de la Eliminación de la Violencia contra la Mujer en su honor, nos recuerda la importancia de educar para la paz, la igualdad de género y el respeto absoluto a los derechos fundamentales en todas las sociedades.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('313e397a-8bbf-49b2-a5d2-0420da519544', 1, 12, 'Padre Billini y Prevención del VIH-SIDA', 'Homenaje al gran filántropo dominicano Francisco X. Billini, quien dedicó su vida entera a la caridad y a la creación de instituciones de asistencia para los sectores más vulnerables de la sociedad en el siglo XIX. Fundador del manicomio de San Lázaro y otros hogares de caridad, su pensamiento humanista buscaba aliviar el sufrimiento de los enfermos y desprotegidos a través de la solidaridad organizada. Su ejemplo de compasión y autogestión social sigue siendo un referente moral para el voluntariado y la responsabilidad social en la República Dominicana hoy día.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('ec4390e5-a8d6-4f36-8953-720a8ff374c8', 6, 12, 'Natalicio de Concepción Bona (1824)', 'Heroína dominicana que, junto a María Trinidad Sánchez y otras valientes mujeres, confeccionó la primera bandera nacional que ondeó en la histórica noche de la Puerta del Conde el 27 de febrero de 1844. Concepción Bona representa la participación activa, decidida y valiente de la mujer en los albores de nuestra independencia. Su labor no fue solo de costura simbólica, sino de compromiso político directo con los ideales trinitarios de Juan Pablo Duarte, demostrando que la libertad nacional se forjó con el aporte igualitario de hombres y mujeres de honor.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('6be208b9-b1af-42f6-a032-6a6b5ac823b5', 26, 1, 'Natalicio de Juan Pablo Duarte', 'Conmemoración del nacimiento del Fundador de la Patria y líder principal de la sociedad secreta La Trinitaria en 1813. Juan Pablo Duarte dedicó su juventud, vida y fortuna familiar a la noble causa de la libertad dominicana, legándonos un ejemplo inigualable de sacrificio, integridad ética y profundo amor por la soberanía nacional. Su pensamiento liberal y democrático fundamentó la creación de nuestra República Dominicana como una nación libre de toda dominación extranjera. Es el mayor referente moral y el guía espiritual de la dominicanidad y la ética ciudadana.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('c62bf047-dcfa-4dc3-a151-c0762c9faa53', 9, 10, 'Día de los Clubes Escolares', 'Promoción de los espacios de participación y liderazgo estudiantil en las escuelas. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('906069ab-2479-46dc-94f6-a1291199c232', 25, 2, 'Natalicio de Matías Ramón Mella', 'Natalicio de Matías Ramón Mella en 1816, estratega militar y valiente luchador que disparó el trabucazo histórico que dio inicio a la independencia nacional en la Puerta de la Misericordia. Mella fue un maestro en la táctica de guerra de guerrillas y un trinitario de convicción inquebrantable que organizó el apoyo popular para la proclamación de la República. Su determinación esa noche de febrero fue el catalizador que rompió el miedo y llamó a las armas a los patriotas, consolidando así el nacimiento de nuestra nación como un estado libre, soberano e independiente de toda dominación extranjera.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('3660e0f1-6cc4-4c98-92c7-a0913dc7960f', 27, 2, 'Independencia Nacional', 'Aniversario de la proclamación de la Independencia Nacional el 27 de febrero de 1844. En la Puerta del Conde, los trinitarios liderados por Sánchez y Mella alzaron la voz de libertad, declarando la separación definitiva de Haití. Este acto de valentía fue el fruto de años de planificación secreta por parte de Juan Pablo Duarte. La noche histórica del trabucazo marcó el inicio de nuestra vida republicana, reafirmando nuestro compromiso con la democracia, la soberanía y la identidad dominicana. Es la festividad patriótica más importante, donde celebramos con orgullo nuestro derecho a ser libres.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4e9f1526-2ab8-4495-b036-fb4ac3eecbff', 9, 3, 'Natalicio de Sánchez y Lectura en Voz Alta', 'Homenaje al natalicio de Francisco del Rosario Sánchez en 1817, prócer y mártir de la patria quien izó la primera bandera dominicana en la Puerta del Conde en 1844. Sánchez fue un defensor incansable de la soberanía nacional que, tras la invasión de 1861, lideró la expedición desde Haití para combatir la anexión a España. Su sacrificio en el cercado, donde fue fusilado gritando "¡Viva la República!", lo consagra junto a Duarte y Mella como uno de los Padres de la Patria. Su vida es un ejemplo de lealtad absoluta a los ideales de libertad y justicia, entregando su sangre por la existencia de la nación.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('3a913283-f937-42e2-80db-c4431df47a54', 19, 3, 'Batalla del 19 de Marzo y Artesanos', 'Significativo enfrentamiento bélico en Azua en 1844, donde las tropas dominicanas demostraron por primera vez su capacidad defensiva contra el ejército invasor haitiano tras la proclamación de la independencia. Liderados por Pedro Santana y Antonio Duvergé, nuestros soldados, a pesar de su inferioridad numérica, lograron una victoria crucial que inyectó confianza en la naciente República. Esta batalla confirmó la determinación del pueblo de defender con las armas su derecho a la soberanía, marcando el inicio de una serie de luchas que asegurarían nuestra libertad permanente frente a cualquier agresión externa.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('55df0ad7-8486-479b-8185-217ad110fd18', 12, 2, 'Conservatorio Nacional de Música', 'Aniversario de la institución dedicada a la formación musical de excelencia. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4fab0942-8cdf-4e3d-9979-4e0702de9e8d', 14, 2, 'Día del Amor y la Amistad', 'Día dedicado a celebrar los vínculos afectivos y la fraternidad entre las personas. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f3524288-8386-47bf-aa7c-98534ea8cf0d', 1, 5, 'Día Internacional del Trabajo', 'Conmemoración de la lucha histórica por los derechos y reivindicaciones laborales alcanzadas por los trabajadores a nivel mundial tras la huelga de Chicago en 1886. Este día resalta la importancia de la dignidad del trabajo como motor de desarrollo de las naciones y el respeto a la jornada laboral justa, la seguridad social y el derecho de asociación. En la República Dominicana, es una fecha para reflexionar sobre los avances en las leyes laborales, la erradicación del trabajo forzoso y la búsqueda constante de condiciones que permitan a cada ciudadano prosperar honestamente a través de su oficio o profesión.', 1, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('5ab43c41-b8da-4646-94e8-e2bef8412564', 5, 5, 'Día del Árbol en RD', 'El Día del Árbol en la República Dominicana es un llamado urgente a la reforestación y conservación de nuestras especies nativas y endémicas. Los árboles son los pulmones de nuestra isla, críticos para la producción de agua, la protección de los suelos contra la erosión y la mitigación de los efectos del cambio climático global. Para los docentes, esta es una jornada de acción pedagógica donde se promueve el amor por la naturaleza y la responsabilidad ambiental. Plantar un árbol es un acto de fe en el futuro y un compromiso inalienable con la sostenibilidad de nuestro ecosistema para las próximas generaciones dominicanas.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('62f23dca-61ad-4c5f-b1a0-fc359ecff1d9', 31, 5, 'Día de las Madres', 'Celebración especial dedicada a honrar y agradecer la labor inconmensurable de las madres dominicanas, pilares fundamentales de la familia y la sociedad. Más allá del festejo comercial, este día reconoce el sacrificio, la entrega y el rol educador que desempeñan las madres en la formación de los valores de las nuevas generaciones. En nuestra cultura, la madre representa la resiliencia y el amor incondicional que sostiene el hogar. Es una oportunidad para que desde el ámbito escolar se fomente el respeto, la gratitud y la valoración de la mujer en su rol de guía y protectora de la vida y el bienestar familiar.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('32897e37-c7bc-4cfb-8cfa-677bba9a4da8', 2, 5, 'Contra el Acoso Escolar', 'Sensibilización para erradicar el bullying y fomentar ambientes escolares seguros. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('1e5c3114-a906-48f6-88cf-224d7f05d7a2', 8, 5, 'Día Mundial de la Cruz Roja', 'Homenaje a la labor humanitaria de la Cruz Roja y la Media Luna Roja. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('c488b92d-9b2b-42a3-8d4f-b009e10341a0', 12, 5, 'Matemáticas y Enfermería', 'Día dedicado al razonamiento lógico y al cuidado profesional de la salud. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2db50f59-1f27-46d2-bb85-3d02f6e0cbe4', 15, 5, 'Día del Agricultor', 'Homenaje a los hombres y mujeres que producen los alimentos de la tierra. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4e73fff6-7f81-4eda-8cd5-a7fb991747cb', 30, 3, 'Batalla del 30 de Marzo', 'Hito militar en Santiago de los Caballeros en 1844, donde el ejército dominicano bajo el mando de José María Imbert y con el apoyo valiente del pueblo cibaeño, repelió exitosamente una gran invasión haitiana. Fue un triunfo determinante donde se utilizaron estrategias de defensa urbana y artillería efectiva para asegurar la supervivencia de la República Dominicana en sus primeros meses de vida. Esta batalla resalta la unidad de las regiones en la causa nacional y el heroísmo de ciudadanos comunes que se convirtieron en soldados para legarnos una patria libre, soberana y protegida de la dominación.', 1, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('29e9e234-5868-4f35-a969-f1992074bd7c', 9, 4, 'Natalicio de Camila Henríquez Ureña', 'Natalicio de Camila Henríquez Ureña en 1894, destacada educadora, crítica literaria, ensayista y pionera del movimiento feminista en la República Dominicana y América Latina. Hija de Salomé Ureña, Camila llevó el legado intelectual de su madre a nuevas fronteras, promoviendo una educación humanista y la igualdad de derechos para la mujer. Su labor académica en el extranjero y en el país fue fundamental para la formación de generaciones de intelectuales. Es un modelo de rigor académico, sensibilidad social y compromiso con la cultura hispana, representando la excelencia del pensamiento femenino dominicano en el mundo.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('03b2aa8f-6cb7-40b4-aa12-db2a01c83161', 13, 4, 'Fundación de la ADP (1970)', 'Aniversario de la fundación de la Asociación Dominicana de Profesores (ADP) en 1970. Esta institución nació en un contexto de lucha por las libertades democráticas y la dignificación del magisterio dominicano. A lo largo de las décadas, la ADP ha sido un actor fundamental en la defensa de los derechos de los maestros y en la búsqueda de una educación pública de calidad para todos los dominicanos. Su labor trasciende la reivindicación salarial, involucrándose en el debate sobre la reforma educativa y el compromiso del Estado con la formación profesional docente y el bienestar integral de la comunidad escolar.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('55fb803d-c410-470b-b220-5af584c71225', 24, 4, 'Ayuntamientos y Revolución de Abril', 'Gesta histórica iniciada el 24 de abril de 1965 con el objetivo noble de restaurar el orden constitucional tras el derrocamiento del gobierno democrático de Juan Bosch. Fue un movimiento de gran participación popular que se transformó en una guerra patria ante la intervención militar extranjera. Los constitucionalistas, liderados por el coronel Caamaño, defendieron palmo a palmo la soberanía y la democracia en las calles de Santo Domingo. Esta lucha representa el sacrificio del pueblo por sus instituciones y su rechazo a cualquier forma de autoritarismo o injerencia externa en los asuntos nacionales.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('5ac0b972-0d40-434e-a757-3ee0b999df9e', 1, 4, 'Técnico Eléctrico y Electrónico', 'Reconocimiento a los profesionales dedicados a la técnica eléctrica y electrónica. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('6f2f97f4-8fca-4536-9d6d-568d14918a8f', 2, 4, 'Concienciación sobre el Autismo', 'Promueve la comprensión y apoyo a las personas con trastornos del espectro autista. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('71cbbd14-1533-4ce5-9204-2dfbcc5a2394', 10, 10, 'Día Internacional de la Salud Mental', 'La salud mental es un componente integral del bienestar general. Este día busca desestigmatizar los trastornos emocionales y promover entornos escolares y sociales que apoyen el equilibrio psicológico, esencial para un aprendizaje efectivo y una vida plena. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('63019946-033f-4534-abee-bfeedf46556a', 11, 10, 'Día Internacional de la Niña', 'Busca reconocer los derechos de las niñas y los desafíos únicos a los que se enfrentan en todo el mundo. Promueve el empoderamiento a través de la educación y la igualdad de oportunidades para que cada niña alcance su máximo potencial. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2364356b-9e3d-45d2-bc0e-b2e37b08100d', 12, 10, 'Día del Encuentro entre Culturas', 'Conmemoración de la diversidad cultural y el legado histórico de nuestra identidad. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('0e6ad1ea-6ada-477a-bd19-26f81b667a99', 13, 10, 'Reducción de Riesgos de Desastres', 'Promoción de una cultura mundial de prevención y mitigación de desastres. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
