INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4121efc3-ab8d-4a92-ac0c-00204f32cfd8', 8, 9, 'Día Mundial de la Fisioterapia', 'Reconocimiento a la importancia de la fisioterapia para la salud y el bienestar físico. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
