INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('05d33f0a-c3e4-490c-91db-a3dac54589d5', 6, 1, 'Día de los Santos Reyes', 'Celebración tradicional de la llegada de los Reyes Magos, día de alegría para los niños. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 1, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('29cf75eb-1bde-465c-bc88-a3350e19d6fa', 12, 1, 'Día de la Resistencia Heroica (1972)', 'Conmemoración del sacrificio de los Palmeros en su lucha por la libertad y la justicia. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('9ad44cef-3fe0-42e7-b5cb-00aed507d4bc', 18, 1, 'Día Nacional del Migrante', 'Reconocimiento a las personas que migran y sus aportes a las sociedades de destino. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4d558182-2864-4a99-b8fb-b8313cddc613', 24, 1, 'Día Internacional de la Educación', 'Resalta el papel de la educación en la paz y el desarrollo sostenible mundial. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('7a60296c-1491-4287-8d9f-8dbd610d7faf', 15, 11, 'Natalicio de José Reyes y Cultura de la Calidad', 'Honra al compositor de nuestro himno y promueve la excelencia educativa. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
