INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b9a41bf9-1a13-4104-99bf-039585e826cb', 18, 11, 'Nacimiento de Máximo Gómez y Aire Puro', 'Honra al Libertador de Cuba y promueve un ambiente libre de contaminación. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('92927215-162f-4b78-80f2-d55068ffae7b', 20, 11, 'Día Universal del Niño', 'Celebración de la fraternidad y comprensión de la infancia en todo el mundo. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b6593516-a620-4ee3-9812-5fc88964529b', 22, 3, 'Día Mundial del Agua', 'Enfoque en la gestión sostenible y el acceso universal al agua dulce. La protección de nuestro entorno natural es una responsabilidad ética inalienable que tenemos con las presentes y futuras generaciones. Esta efeméride ambiental nos recuerda la fragilidad de nuestros ecosistemas, desde las cuencas hidrográficas hasta la biodiversidad marina de nuestra isla. Promover una conciencia ecológica activa en nuestras escuelas es vital para enfrentar los desafíos del cambio climático y garantizar la sostenibilidad de nuestros recursos naturales. Cuidar el medio ambiente es, en última instancia, cuidar la casa de todos y asegurar la continuidad de la vida en el planeta.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('4f305efd-ac10-4c83-9eea-f2e6bb437bba', 9, 2, 'Ulises Francisco Espaillat', 'Homenaje al presidente civilista y ejemplo de probidad administrativa. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
