INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('2e79a867-0ee3-4faf-9fdb-eec9ca57d429', 22, 9, 'Prevención de Desastres y Emergencias', 'Enfoque en la preparación y mitigación de riesgos ante desastres naturales. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('3fd9ff9e-3afc-4492-8a51-f2dc9bd03bf3', 23, 9, 'Día de las Lenguas de Señas', 'Fomenta la inclusión y el reconocimiento de la lengua de señas como patrimonio cultural. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('52060051-0a8b-47b4-baa3-89e4a6d14e5d', 25, 9, 'Día Mundial de los Farmacéuticos', 'Reconocimiento al papel fundamental de los farmacéuticos en el sistema de salud. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('9d67b829-a42d-47d7-99df-30920ad21d25', 26, 9, 'Prevención del Embarazo en Adolescentes', 'Sensibilización sobre el impacto del embarazo temprano en el desarrollo de la juventud. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('25c77c51-7af7-41c7-9ff1-7a73e6569aaf', 26, 9, 'Día Mundial de la Salud Ambiental', 'Enfoque en la relación entre el medio ambiente y la salud humana. La protección de nuestro entorno natural es una responsabilidad ética inalienable que tenemos con las presentes y futuras generaciones. Esta efeméride ambiental nos recuerda la fragilidad de nuestros ecosistemas, desde las cuencas hidrográficas hasta la biodiversidad marina de nuestra isla. Promover una conciencia ecológica activa en nuestras escuelas es vital para enfrentar los desafíos del cambio climático y garantizar la sostenibilidad de nuestros recursos naturales. Cuidar el medio ambiente es, en última instancia, cuidar la casa de todos y asegurar la continuidad de la vida en el planeta.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b594eb05-d05d-47ce-88ba-75aaf38e48e5', 27, 9, 'Día del Biólogo', 'Reconocimiento a los profesionales dedicados al estudio de la vida y la biodiversidad. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
