INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('764f143f-3cfa-48e4-a1b2-c5eb2ed8ad90', 29, 9, 'Día de los Derechos de la Niñez', 'Protección y promoción de los derechos fundamentales de todos los niños y niñas. Esta fecha busca concienciar sobre la importancia de garantizar un entorno seguro, educación de calidad y salud para todos los menores, asegurando que su voz sea escuchada en el desarrollo de sus comunidades. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
