INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('f8a4b1cb-37d8-44d6-b1be-efd163bd68c2', 3, 12, 'Personas con Discapacidad y No Uso del Plaguicida', 'Promueve la inclusión social y la agricultura ecológica sin químicos. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('b19e177e-de6a-40da-91fc-6c36422403f8', 5, 12, 'Llegada de Colón (1492) y Día del Suelo', 'Marca el inicio del proceso histórico colonial y la protección del recurso suelo. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
