INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('80196121-a61f-403f-a777-21ca39b5b33a', 1, 3, 'Día de la Cero Discriminación', 'Llamado a la igualdad y al respeto de los derechos de todas las personas. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('764dbfca-9b61-4d69-ba97-82ff3621a378', 3, 3, 'Asociaciones de Padres y Naturaleza', 'Une a la comunidad escolar y promueve la protección de los recursos naturales. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('6c39d519-03f0-40d0-a783-d31099d43698', 6, 3, 'Natalicio de José Francisco Peña Gómez', 'Recuerdo del líder político y defensor de las libertades democráticas. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('87763609-b417-4c1a-9407-4fa1a0983436', 7, 3, 'Natalicio de Manuel del Cabral', 'Homenaje al gran poeta dominicano, exponente de la poesía negroide y social. Esta efeméride constituye un pilar fundamental de nuestra identidad nacional. Recordar y estudiar estos eventos patrios permite a los estudiantes comprender el sacrificio de los fundadores de la República y la importancia de defender nuestra soberanía, libertad y valores democráticos en el presente. Es a través del conocimiento de nuestra historia que fortalecemos el orgullo de ser dominicanos y nos comprometemos a construir un país más justo, ético y próspero para todos los ciudadanos, honrando siempre el legado de sacrificio y valentía de nuestros próceres y heroínas.', 0, 'PATRIA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('0d5e1ae3-e831-4e2f-b183-060cc7e7764d', 8, 3, 'Día Internacional de la Mujer', 'Día de lucha por la igualdad de género y el empoderamiento de la mujer. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('300d1742-779e-4e74-aeae-bce90555d348', 11, 3, 'Día de los Bomberos Municipales', 'Reconocimiento a quienes arriesgan su vida por la seguridad de la comunidad. Este día nos invita a reflexionar sobre la importancia de la convivencia armónica, la solidaridad y el respeto mutuo entre todos los ciudadanos. Las efemérides sociales subrayan los lazos de fraternidad que nos unen y la necesidad de trabajar juntos por el bienestar común, la equidad y la justicia social. Es una oportunidad para que la comunidad educativa promueva valores de paz, cooperación y compromiso con los sectores más vulnerables, recordando que una sociedad fuerte se construye sobre la base de la empatía, el diálogo y la responsabilidad compartida por el progreso nacional.', 0, 'SOCIAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('d0a796bf-6432-4cab-95fc-ba51c2515a0e', 14, 3, 'Día del Pi y Altas Capacidades', 'Fomenta el interés por las matemáticas y la atención al talento escolar. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('68181fd9-1dea-454e-bc45-00af67321224', 23, 3, 'Día de la Rehabilitación', 'Promoción del acceso a los servicios de rehabilitación para la autonomía personal. La salud es un derecho fundamental y un requisito indispensable para el pleno desarrollo de las capacidades humanas. Esta fecha busca concienciar a la comunidad escolar sobre la importancia de la prevención, el autocuidado y la promoción de estilos de vida saludables. Entender la relación entre el bienestar físico, mental y social permite a los estudiantes tomar decisiones informadas y responsables que impacten positivamente en su calidad de vida y en la de sus familias. La salud es la base de un aprendizaje efectivo y de una vida con propósito, dignidad y plenitud integral.', 0, 'SALUD');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('fe057ac2-1997-4883-b26c-dcf9e5bd7334', 26, 3, 'Día Mundial del Clima', 'Concienciación sobre el cambio climático y sus efectos en el planeta. La protección de nuestro entorno natural es una responsabilidad ética inalienable que tenemos con las presentes y futuras generaciones. Esta efeméride ambiental nos recuerda la fragilidad de nuestros ecosistemas, desde las cuencas hidrográficas hasta la biodiversidad marina de nuestra isla. Promover una conciencia ecológica activa en nuestras escuelas es vital para enfrentar los desafíos del cambio climático y garantizar la sostenibilidad de nuestros recursos naturales. Cuidar el medio ambiente es, en última instancia, cuidar la casa de todos y asegurar la continuidad de la vida en el planeta.', 0, 'AMBIENTAL');
INSERT OR REPLACE INTO ephemerides (id, day, month, title, description, is_holiday, category) VALUES ('e92f5138-4045-44b4-99f1-7de5d266bce2', 27, 3, 'Día Internacional del Teatro', 'Homenaje a las artes escénicas como vehículo de expresión humana. La conmemoración de esta fecha en el calendario escolar busca potenciar el desarrollo integral de los estudiantes, fomentando la curiosidad intelectual, el respeto por el conocimiento y la valoración de las instituciones que sustentan nuestra sociedad. La educación es el motor del progreso y estas fechas nos recuerdan que cada área del saber contribuye a formar ciudadanos críticos, creativos y capaces de transformar su entorno de manera positiva. Es un día para celebrar el aprendizaje continuo y la búsqueda de la excelencia en la formación de las futuras generaciones del país.', 0, 'EDUCATIVA');
